mapper.select:
SELECT COUNT(1)
FROM rag_chunks
WHERE doc_id = #{docId,jdbcType=VARCHAR}

mapper.update:
UPDATE rag_chunks
SET index_status = #{indexStatus,jdbcType=VARCHAR},
    error_message = #{errorMessage,jdbcType=VARCHAR}
WHERE doc_id = #{docId,jdbcType=VARCHAR}

UPDATE rag_chunks
SET embedding_model = #{embeddingModel,jdbcType=VARCHAR},
    embedding_dimension = #{embeddingDimension,jdbcType=INTEGER}
WHERE doc_id = #{docId,jdbcType=VARCHAR}
